style.css:
@-moz-document url-prefix("https://"), url-prefix("http://") {
* {
    background-image: linear-gradient(135deg, #1e1e1e, #0a0a0a), 
                      radial-gradient(circle, #007bff 0%, #ff8c00 50%, #ffffff 75%, #000000 100%);
    background-blend-mode: overlay;
    color: white !important;
    border-color: rgba(255, 255, 255, 0.3) !important;
    transition: all 0.3s ease-in-out;
  }

  body {
    background: radial-gradient(circle at center, #007bff, #ff8c00, #000000);
    color: white;
    font-family: 'Segoe UI', sans-serif;
  }

  a, h1, h2, h3, h4, h5, h6, strong, b {
    color: #ffa500 !important;
    text-shadow: 0 0 5px #007bff;
  }

  button, input, textarea, select {
    background-color: rgba(0, 0, 0, 0.6) !important;
    color: #ffffff !important;
    border: 2px solid #007bff !important;
    border-radius: 8px;
    padding: 5px 10px;
  }

  ::selection {
    background: #ff8c00;
    color: #000;
  }

  img {
    filter: hue-rotate(45deg) contrast(1.2) brightness(0.9);
    border-radius: 12px;
  }
}
